/**
 * TASK: Use the Adapter pattern so old code fits a new interface.
 *
 * LegacyThermometer (below, complete) cannot be changed: it reports readings as
 * strings such as "72F" in Fahrenheit. Everything else in the program only knows
 * the TemperatureSource interface, which reports Celsius as a double.
 *
 * Complete FahrenheitSensorAdapter so it implements TemperatureSource by asking the
 * wrapped thermometer for its reading and converting it:
 *   celsius = (fahrenheit - 32) * 5 / 9, rounded to 2 decimals
 *   label() returns the thermometer id followed by " (C)"
 *
 * Example: new FahrenheitSensorAdapter(new LegacyThermometer("roof", 212))
 *          celsius() -> 100.0 and label() -> "roof (C)"
 */
interface TemperatureSource {

    double celsius();

    String label();
}

class LegacyThermometer {

    private final String id;
    private final int fahrenheit;

    LegacyThermometer(String id, int fahrenheit) {
        this.id = id;
        this.fahrenheit = fahrenheit;
    }

    String getId() {
        return id;
    }

    /** Reading as a string such as "72F" -- degrees followed by the letter F. */
    String readFahrenheit() {
        return fahrenheit + "F";
    }
}

public class FahrenheitSensorAdapter implements TemperatureSource {

    private final LegacyThermometer thermometer;

    public FahrenheitSensorAdapter(LegacyThermometer thermometer) {
        this.thermometer = thermometer;
    }

    @Override
    public double celsius() {
        // TODO: read the Fahrenheit string, drop the trailing "F", convert, round to 2 decimals
        return 0.0;
    }

    @Override
    public String label() {
        // TODO: the wrapped thermometer's id plus " (C)"
        return "";
    }
}

