public class FahrenheitSensorAdapterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        TemperatureSource boiling = new FahrenheitSensorAdapter(new LegacyThermometer("roof", 212));
        check("212F in Celsius", 100.0, boiling.celsius());
        check("label of the roof sensor", "roof (C)", boiling.label());

        TemperatureSource room = new FahrenheitSensorAdapter(new LegacyThermometer("lab", 72));
        check("72F in Celsius rounded", 22.22, room.celsius());
        check("label of the lab sensor", "lab (C)", room.label());

        TemperatureSource freezing = new FahrenheitSensorAdapter(new LegacyThermometer("yard", 32));
        check("32F in Celsius", 0.0, freezing.celsius());

        TemperatureSource cold = new FahrenheitSensorAdapter(new LegacyThermometer("pole", -40));
        check("-40F in Celsius", -40.0, cold.celsius());

        TemperatureSource[] sensors = {boiling, room, freezing};
        double sum = 0.0;
        for (TemperatureSource s : sensors) {
            sum += s.celsius();
        }
        check("sum through the interface", 122.22, Math.round(sum * 100.0) / 100.0);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

