interface TemperatureSource {

    double celsius();

    String label();
}

class LegacyThermometer {

    private final String id;
    private final int fahrenheit;

    LegacyThermometer(String id, int fahrenheit) {
        this.id = id;
        this.fahrenheit = fahrenheit;
    }

    String getId() {
        return id;
    }

    /** Reading as a string such as "72F" -- degrees followed by the letter F. */
    String readFahrenheit() {
        return fahrenheit + "F";
    }
}

public class FahrenheitSensorAdapter implements TemperatureSource {

    private final LegacyThermometer thermometer;

    public FahrenheitSensorAdapter(LegacyThermometer thermometer) {
        this.thermometer = thermometer;
    }

    @Override
    public double celsius() {
        String reading = thermometer.readFahrenheit();
        String digits = reading.substring(0, reading.length() - 1);
        int fahrenheit = Integer.parseInt(digits);
        double c = (fahrenheit - 32) * 5.0 / 9.0;
        return Math.round(c * 100.0) / 100.0;
    }

    @Override
    public String label() {
        return thermometer.getId() + " (C)";
    }
}
